export function generateFormattedPrompt(
  item: PagePromptItem,
  lang: "id" | "en",
  aspectRatioId: AspectRatioType,
): string {
  const ratio = ASPECT_RATIO_OPTIONS.find((r) => r.id === aspectRatioId);
  const baseText =
    lang === "id" ? item.coreVisualIndonesia : item.coreVisualInggris;

  if (!ratio) return baseText;

  const prefix = lang === "id" ? "Aspek Rasio" : "Aspect Ratio";
  const ratioFormat = lang === "id" ? ratio.ratioFormatId : ratio.ratioFormatEn;

  return `${baseText}\n\n${prefix}: ${ratioFormat}\nParameter: ${ratio.midjourneyAr}`;
}
